<template>
  <section class="tab-panel mutual-comments" data-panel="mutualComments" :hidden="activeTab!=='mutualComments'" :aria-label="t(&quot;首页跟评&quot;)">
    <div class="fq-panel-root mc-card">
      <header class="fq-header"><div class="fq-header-title-wrap"><h2 class="fq-header-title">{{ t("首页跟评") }}</h2><span class="fq-header-subtitle">{{ t("发现互关意愿 · 用评论建立联系") }}</span></div><PanelActionBar class="fq-header-actions"><PanelIconButton :icon="RefreshCw" :label="t(&quot;刷新记录&quot;)" :disabled="busy" @click="refresh" /><PanelIconButton :icon="Settings" :label="t(&quot;首页跟评设置&quot;)" :disabled="!state" @click="openSettings" /><PanelIconButton :icon="Play" :label="t(&quot;立即采集与打标&quot;)" :disabled="busy||!state?.config.scanEnabled||state?.running.scan" @click="act('runScan')" /><PanelIconButton :icon="MessageCircle" :label="t(&quot;立即评论&quot;)" :disabled="busy||!state?.config.commentEnabled||state?.running.comment" @click="act('runComments')" /></PanelActionBar></header>
      <div v-if="error||state?.config.scanError||state?.config.commentError" class="fq-alert fq-alert-error" role="alert">{{ t(error||state.config.scanError||state.config.commentError) }}</div><div v-if="notice" class="mc-notice" role="status">{{ t(notice) }}</div>
      <div class="fq-summary-bar"><span class="fq-summary-item">{{ t("总记录") }}<strong>{{ t(state?.allTotal||0) }}</strong></span><span v-for="key in summaryStates" :key="key" class="fq-summary-item">{{ t(status(key)) }} <strong :class="'mc-count-'+key">{{ t(state?.counts?.[key]||0) }}</strong></span><span class="fq-summary-time">{{ t("最近扫描：") }}{{ t(date(state?.scans[0]?.at)) }}</span></div>
      <div class="mc-schedules"><div v-for="phase in phases" :key="phase.key" class="mc-schedule"><span class="mc-dot" :class="{enabled:state?.config[phase.key+'Enabled']}"></span><strong>{{ t(phase.label) }}</strong><span>{{ t(state?.running[phase.key]?t("正在执行"):state?.config[phase.key+'Enabled']?t('nextRun',{time:date(state.config[phase.key==='scan'?'nextScanAt':'nextCommentAt'])}):t("已关闭")) }}</span><span class="mc-budget">{{ phase.key==='scan'?t('batchLimit',{count:state?.config.batchSize||10}):t('replyLimits',{perRun:state?.config.perRun||3,daily:state?.config.dailyLimit||10}) }}</span></div></div>
      <div class="fq-filter-tabs mc-state-tabs" role="group" :aria-label="t(&quot;评论状态筛选&quot;)"><button v-for="key in ['all',...allStates]" :key="key" type="button" class="fq-filter-tab" :class="{active:statusFilter===key}" :aria-pressed="statusFilter===key" @click="statusFilter=key;changeFilter()">{{ t(key==='all'?t("全部状态"):status(key)) }}</button></div>
      <div class="mc-list-toolbar"><div class="fq-filter-controls"><label class="mc-tag-filter">{{ t("AI 标签") }}<PanelSelect v-model="tagFilter" class="fq-select" :aria-label="t(&quot;AI 标签筛选&quot;)" @change="changeFilter"><option value="all">{{ t("全部标签") }}</option><option v-for="tag in tagKeys" :key="tag" :value="tag">{{ t(tagName(tag)) }}（{{ t(state?.tags?.[tag]||0) }}）</option></PanelSelect></label><input v-model="query" class="fq-search-input" type="search" :aria-label="t(&quot;搜索首页跟评&quot;)" :placeholder="t(&quot;搜索账号、原帖或评论…&quot;)" @input="changeFilter"><span v-if="selected.size" class="mc-selection">{{ t('selectedCount',{count:selected.size}) }}<button type="button" class="fq-btn fq-btn-secondary" @click="copySelected">{{ t("复制原帖链接") }}</button><button type="button" class="fq-btn fq-btn-secondary" @click="selected=new Set()">{{ t("取消选择") }}</button></span></div>
        <div class="monitor-pagination fq-pagination"><label class="fq-pagesize-label page-size-label">{{ t("每页") }}<PanelSelect v-model.number="pageSize" class="fq-select fq-pagesize-select" :aria-label="t(&quot;每页条数&quot;)" @change="changePageSize"><option v-for="n in [10,20,50,100]" :key="n" :value="n">{{ t(n) }}</option></PanelSelect></label><span class="page-summary fq-page-summary">{{ t('pageSummary',{page:state?.page||1,total:state?.total||0}) }}</span><div class="page-actions fq-page-actions"><button class="icon-button secondary fq-page-nav-btn" :aria-label="t(&quot;上一页&quot;)" :disabled="page<=1||busy" @click="goPage(page-1)">‹</button><template v-for="(n,index) in pageNumbers" :key="index"><span v-if="n==='…'" class="fq-page-ellipsis">…</span><button v-else class="fq-page-btn" :class="{active:page===n}" :aria-label="t('pageNumber',{page:n})" :aria-current="page===n?'page':undefined" :disabled="busy" @click="goPage(n)">{{ t(n) }}</button></template><button class="icon-button secondary fq-page-nav-btn" :aria-label="t(&quot;下一页&quot;)" :disabled="page>=totalPages||busy" @click="goPage(page+1)">›</button></div></div>
      </div>
      <div class="fq-table-wrap mc-table"><table class="fq-table"><colgroup><col class="mc-col-select"><col class="mc-col-source"><col class="mc-col-tag"><col class="mc-col-priority"><col class="mc-col-reply"><col class="mc-col-status"><col class="mc-col-time"><col class="mc-col-actions"></colgroup><thead><tr><th class="mc-center"><input type="checkbox" :aria-label="t(&quot;选择本页全部记录&quot;)" :checked="pageSelected" :indeterminate="selected.size>0&&!pageSelected" :disabled="!state?.items.length" @change="selectPage($event.target.checked)"></th><th>{{ t("原帖") }}</th><th class="mc-center">{{ t("AI 标签") }}</th><th class="mc-priority-column" :aria-sort="sortOrder==='desc'?'descending':'ascending'"><button class="mc-sort" type="button" :aria-label="sortOrder==='desc'?t(&quot;权重当前降序，点击升序&quot;):t(&quot;权重当前升序，点击降序&quot;)" @click="toggleWeightSort">{{ t("权重") }}<span class="mc-sort-directions" aria-hidden="true"><span :class="{active:sortOrder==='asc'}">▲</span><span :class="{active:sortOrder==='desc'}">▼</span></span></button></th><th>{{ t("评论内容") }}</th><th class="mc-center">{{ t("评论状态") }}</th><th class="mc-center">{{ t("时间") }}</th><th class="mc-center">{{ t("操作") }}</th></tr></thead><tbody><tr v-if="!state?.items.length"><td colspan="8" class="mc-empty">{{ t(!state?(error?t("请保留已登录的 X 页面后刷新"):t("正在读取账号与记录…")):query||statusFilter!=='all'||tagFilter!=='all'?t("没有符合筛选条件的记录"):t("暂无帖子记录。先开启采集与打标，再按需开启评论。")) }}</td></tr><tr v-for="row in state?.items||[]" :key="row.postId" :class="{'fq-row-selected':selected.has(row.postId)}"><td class="mc-center"><input type="checkbox" :aria-label="t('selectPost',{handle:row.handle})" :checked="selected.has(row.postId)" @change="toggleRow(row.postId,$event.target.checked)"></td><td><a class="mc-author" :href="row.url" target="_blank" rel="noopener noreferrer">@{{ row.handle }}</a><p class="mc-excerpt" :title="row.text">{{ row.text }}</p></td><td class="mc-center"><span class="mc-status" :class="'is-'+row.tag" :title="(t(row.tagReason) || t(&quot;尚未完成 AI 打标&quot;))">{{ t(tagName(row.tag)) }}</span></td><td class="mc-priority-column"><span v-if="['ready','generating','draft'].includes(row.status)" class="mc-priority-value" tabindex="0" :data-panel-tip="t(priorityTip(row))" :aria-label="t('replyWeight',{weight:row.priority?.weight??0})">{{ t(row.priority?.weight??0) }}</span><span v-else class="mc-priority-empty">—</span></td><td><span v-if="row.replyCache" class="mc-status" :title="t('reusedReply',{post:row.replyCache.sourcePostId})">{{ t("复用") }}</span><p class="mc-excerpt" :title="(row.reply || t(row.error))">{{ (row.reply || t(row.error) || (row.tag==='mutual'?t("等待评论调度"):'—')) }}</p></td><td class="mc-center"><span class="mc-status" :class="'is-'+row.status">{{ t(status(row.status)) }}</span><div v-if="['ready','generating','draft'].includes(row.status)" class="mc-time">{{ t(row.following===false?t("未关注"):row.following===true?t("已关注"):t("关注未知")) }}</div></td><td class="mc-center mc-time">{{ t(date(row.finishedAt||row.createdAt)) }}</td><td class="mc-center"><PanelIconButton :icon="ListTree" :label="t(&quot;查看评论回溯&quot;)" @click="openDetail(row)" /></td></tr></tbody></table></div>
    </div>
    <ActionSettingsDrawer ref="settingsDrawer" :title="t(&quot;首页跟评设置&quot;)">
      <div class="mc-form"><section v-for="phase in phases" :key="phase.key" class="mc-config-section"><h3>{{ t(phase.label) }}</h3><p>{{ t(phase.key==='scan'?t("定时读取首页新帖，批量识别互关意愿并入库。"):t("从已打标的互关帖中生成评论并发布，不主动关注。")) }}</p><label><input v-model="draft[phase.key+'Enabled']" type="checkbox" @change="draft[phase.key+'BotId']='';inspectEngine(phase.key)">{{ t(phase.key==='scan'?t("采集开关"):t("评论开关")) }}</label>
      <template v-if="draft[phase.key+'Enabled']"><label>{{ t("AI 引擎") }}<PanelSelect v-model="draft[phase.key+'Provider']" @change="draft[phase.key+'BotId']='';inspectEngine(phase.key)"><option value="">{{ t("请选择 AI 引擎") }}</option><option v-for="engine in GENERATION_ENGINES" :key="engine.value" :value="engine.value">{{ t(engine.label) }}</option></PanelSelect></label><label v-if="isLocalAiProvider(draft[phase.key+'Provider'])">{{ t("生成会话") }}<PanelSelect truncate-selection class="ai-session-select" :id="'mc-session-'+phase.key" v-model="draft[phase.key+'BotId']" :title="(engineStates[phase.key]?.bots||[]).find(b=>b.id===draft[phase.key+'BotId'])?.title||(engineStates[phase.key]?.bots||[]).find(b=>b.id===draft[phase.key+'BotId'])?.name"><option value="">{{ t("请选择会话") }}</option><option v-if="draft[phase.key+'BotId']&&!(engineStates[phase.key]?.bots||[]).some(bot=>bot.id===draft[phase.key+'BotId'])" :value="draft[phase.key+'BotId']">{{ t("已保存的会话") }}{{ t(engineMessages[phase.key]==='正在检测连接…'?t("（检测中）"):t("（待确认连接）")) }}</option><option v-for="bot in engineStates[phase.key]?.bots||[]" :key="bot.id" :value="bot.id" :title="bot.title||bot.name">{{ bot.name }}</option></PanelSelect></label><p class="mc-engine-message" role="status">{{ t(engineMessages[phase.key]) }}</p><div v-if="draft[phase.key+'Provider']&&draft[phase.key+'Provider']!=='grok'" class="mc-engine-actions"><button type="button" class="fq-btn fq-btn-secondary" @click="configureEngine(phase.key)">{{ t("管理连接") }}</button><button type="button" class="fq-btn fq-btn-secondary" @click="inspectEngine(phase.key)">{{ t("重新检测") }}</button></div></template>
      <label>{{ t("执行间隔（分钟）") }}<span class="mc-interval-range"><input v-model.number="draft[phase.key+'IntervalMinutes']" :aria-label="t('minimumInterval',{phase:t(phase.label)})" type="number" min="1" max="1439"><span>{{ t("至") }}</span><input v-model.number="draft[phase.key+'IntervalMaxMinutes']" :aria-label="t('maximumInterval',{phase:t(phase.label)})" type="number" min="2" max="1440"></span></label>
      <template v-if="phase.key==='scan'"><label>{{ t("加载更多次数") }}<InfoTip :text="t(&quot;优先通过首页接口分页，相当于下拉加载。0 表示仅取首页第一批；遇到已保存的帖子锚点且整页没有新帖时提前结束。每次使用临时窗口，结束后关闭。&quot;)" /><input v-model.number="draft.scrollRounds" type="number" min="0" max="30"></label><label>{{ t("每批打标帖子数") }}<InfoTip :text="t(&quot;将多条新帖合并为一次 AI 请求，按引擎输入长度自动分批；已保存的标签不重复请求。&quot;)" /><input v-model.number="draft.batchSize" type="number" min="1" max="100"></label></template>
      <template v-else><label>{{ t("每轮评论上限") }}<input v-model.number="draft.perRun" type="number" min="1" max="10"></label><label>{{ t("每日评论上限") }}<InfoTip :text="t(&quot;按北京时间统计；待核实的发送也计入上限。发送之间随机间隔1至3分钟。&quot;)" /><input v-model.number="draft.dailyLimit" type="number" min="1" max="1000"></label><label><input v-model="draft.followBackSuffixEnabled" type="checkbox">{{ t("来关必回") }}<InfoTip :text="t(&quot;与关注队列一致，按评论语言追加互关邀请，例如：关注我，必回关！🤝。已有同义文案不重复；长度不足时保留草稿，不截断正文。&quot;)" /></label><CommentTagsSettings :settings="draft" @update="Object.assign(draft,$event)" /></template></section></div><template #footer><p v-if="settingsError" class="mc-error mc-save-error" role="alert" tabindex="-1">{{ t(settingsError) }}</p><button :disabled="busy" @click="save">{{ t(busy?t("保存中…"):t("保存配置")) }}</button></template>
    </ActionSettingsDrawer>
<PanelModal ref="saveResult" class="mc-save-result" :title="t(&quot;保存成功&quot;)"><p role="status">{{ t("配置已保存到本机，刷新或重新打开后仍会保留。") }}</p><template #footer><button type="button" @click="saveResult.close()">{{ t("确定") }}</button></template></PanelModal>
    <ActionSettingsDrawer ref="detailDrawer" :title="t(&quot;评论回溯&quot;)"><div v-if="detail" class="mc-detail"><p>{{ t(status(detail.status)) }} · {{ t(date(detail.createdAt)) }}</p><a :href="detail.url" target="_blank" rel="noopener noreferrer">{{ t('openPost',{handle:detail.handle}) }}</a><h3>{{ t("原帖内容") }}</h3><p>{{ detail.text }}</p><h3>{{ t("判断依据") }}</h3><p>{{ t(tagName(detail.tag)) }} · {{ t(detail.tagReason||t("尚未完成判断")) }}</p><p v-if="detail.tagBatchId" class="mc-time">{{ t("打标批次：") }}{{ t(detail.tagBatchId) }} · {{ t(date(detail.taggedAt)) }}</p><p v-if="detail.decorationSettings">{{ t("随机标签：") }}{{ t(detail.decorationSettings.quoteTagsEnabled?t("已开启"):t("未开启")) }}{{ t("· 来关必回：") }}{{ t(detail.decorationSettings.followBackSuffixEnabled?t("已开启"):t("未开启")) }}</p><p v-if="detail.tagCache">{{ t("标签复用：原帖") }}{{ t(detail.tagCache.sourcePostId) }}</p><p v-if="detail.replyCache">{{ t("评论复用：原帖") }}{{ t(detail.replyCache.sourcePostId) }} · {{ t(date(detail.replyCache.matchedAt)) }}</p><h3>{{ t("评论内容") }}</h3><p>{{ (detail.reply || t("尚未生成")) }}</p><p v-if="detail.knowledge?.wisdomVersion">{{ t('wisdomVersion',{version:detail.knowledge.wisdomVersion}) }}</p><p v-if="detail.knowledge?.warning">{{ t(detail.knowledge.warning) }}</p><p v-if="detail.error" class="mc-error">{{ t(detail.error) }}</p><a v-if="detail.publishedPostUrl" :href="detail.publishedPostUrl" target="_blank" rel="noopener noreferrer">{{ t("查看已发布评论") }}</a><button v-if="detail.status==='uncertain'&&detail.publishAttemptedAt" :disabled="busy" @click="act('verify',{postId:detail.postId})">{{ t("核实发布结果") }}</button><p v-if="tagBatch?.error" class="mc-error">{{ t("打标：") }}{{ t(tagBatch.error) }}</p><details v-if="tagBatch?.raw"><summary>{{ t("批量打标原始结果") }}</summary><pre>{{ tagBatch.raw }}</pre></details><details v-if="detail.raw"><summary>{{ t("AI 原始结果") }}</summary><pre>{{ detail.raw }}</pre></details></div></ActionSettingsDrawer>
  </section>
</template>
<script setup>
import {t,locale} from '../../../shared/i18n.js';

import {isLocalAiProvider} from '../../../features/grok/grok-local.js';
import PanelSelect from "../components/PanelSelect.vue";
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';
import {Settings,Play,RefreshCw,ListTree,MessageCircle} from 'lucide';
import {panelNavigationController} from '../composables/usePanelNavigation.js';
import PanelActionBar from '../components/PanelActionBar.vue';
import PanelIconButton from '../components/PanelIconButton.vue';
import PanelModal from '../components/PanelModal.vue';
import ActionSettingsDrawer from '../components/ActionSettingsDrawer.vue';
import CommentTagsSettings from '../components/CommentTagsSettings.vue';
import InfoTip from '../components/InfoTip.vue';
import {GENERATION_ENGINES,inspectGenerationEngine} from '../generation-choice.js';
const {activeTab}=panelNavigationController;
const state=ref(null),busy=ref(false),error=ref(''),notice=ref(''),page=ref(1),draft=reactive({}),settingsError=ref(''),saveResult=ref(null),settingsDrawer=ref(null),detailDrawer=ref(null),detail=ref(null),tagBatch=ref(null);
const pageSize=ref([10,20,50,100].includes(Number(localStorage.getItem('mutualCommentsPageSize')))?Number(localStorage.getItem('mutualCommentsPageSize')):20),selected=ref(new Set());
const allStates=['idle','ready','generating','draft','publishing','posted','skipped','failed','uncertain'],summaryStates=['ready','generating','posted','failed','uncertain'];
const phases=[{key:'scan',label:'采集与打标'},{key:'comment',label:'首页跟评'}],tagKeys=['pending','tagging','mutual','not_mutual','uncertain','failed'];
const tagName=value=>({pending:'待打标',tagging:'打标中',mutual:'互关帖',not_mutual:'非互关帖',uncertain:'不确定',failed:'打标失败'}[value]||'待打标');
const totalPages=computed(()=>Math.max(1,Math.ceil((state.value?.total||0)/pageSize.value)));
const pageSelected=computed(()=>Boolean(state.value?.items.length)&&state.value.items.every(row=>selected.value.has(row.postId)));
const pageNumbers=computed(()=>{const pages=[...new Set([1,totalPages.value,page.value-1,page.value,page.value+1])].filter(n=>n>0&&n<=totalPages.value).sort((a,b)=>a-b),result=[];for(const n of pages){if(result.length&&n-pages[pages.indexOf(n)-1]>1)result.push('…');result.push(n);}return result;});
const sortOrder=ref('desc');
function toggleWeightSort(){sortOrder.value=sortOrder.value==='desc'?'asc':'desc';changeFilter();}
const query=ref(''),statusFilter=ref('all'),tagFilter=ref('all'),engineStates=reactive({}),engineMessages=reactive({});
let sequence=0;const engineSequence={scan:0,comment:0};
const date=value=>value?new Date(value).toLocaleString(locale.value,{hour12:false}):'—';
const status=value=>({idle:'未入队',ready:'待评论',generating:'生成中',draft:'待发布',publishing:'发布中',posted:'已评论',skipped:'已跳过',failed:'未完成',uncertain:'待核实'}[value]||value);
const priorityTip=row=>t('priorityHelp',{score:row.priority?.engagementScore??t('未知，暂不追加互动分')});
const scanStatus=row=>row.status==='completed'?`采集 ${row.received} 条，新增 ${row.added} 条`:row.error||'扫描中';
async function request(action,extra={}){const result=await chrome.runtime.sendMessage({cmd:'mutualComments',action,...extra});if(!result?.ok)throw Error(result?.error||'请求失败');return result;}
async function refresh(){const ticket=++sequence;try{const result=await request('state',{page:page.value,pageSize:pageSize.value,status:statusFilter.value,sortOrder:sortOrder.value,tag:tagFilter.value,q:query.value});if(ticket!==sequence)return;if(state.value&&result.account.accountId!==state.value.account.accountId){settingsDrawer.value?.close();detailDrawer.value?.close();detail.value=null;}state.value=result;page.value=result.page;selected.value=new Set([...selected.value].filter(id=>result.items.some(row=>row.postId===id)));error.value='';if(detail.value)detail.value=result.items.find(row=>row.postId===detail.value.postId)||detail.value;}catch(e){if(ticket===sequence)error.value=e.message;}}
function changeFilter(){page.value=1;selected.value=new Set();refresh();}
function goPage(n){page.value=n;selected.value=new Set();refresh();}
function changePageSize(){localStorage.setItem('mutualCommentsPageSize',String(pageSize.value));changeFilter();}
function toggleRow(id,checked){const next=new Set(selected.value);checked?next.add(id):next.delete(id);selected.value=next;}
function selectPage(checked){selected.value=new Set(checked?(state.value?.items||[]).map(row=>row.postId):[]);}
async function copySelected(){try{await navigator.clipboard.writeText(state.value.items.filter(row=>selected.value.has(row.postId)).map(row=>row.url).join('\n'));notice.value='已复制所选原帖链接';}catch(e){error.value='复制失败：'+e.message;}}
async function act(action,extra={}){busy.value=true;error.value='';try{const result=await request(action,extra);notice.value=result.notice||'已安排扫描，执行进度会自动刷新';await refresh();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function openDetail(row){try{const result=await request('detail',{postId:row.postId});detail.value=result.row;tagBatch.value=result.tagBatch;detailDrawer.value.open();}catch(e){error.value=e.message;}}
function openSettings(){Object.assign(draft,state.value.config);settingsError.value='';settingsDrawer.value.open();for(const {key} of phases)if(draft[key+'Enabled'])inspectEngine(key);}
async function save(){busy.value=true;settingsError.value='';try{state.value=await request('save',{config:{...draft}});settingsDrawer.value.close();notice.value='两个调度的配置已保存';saveResult.value.open();}catch(e){settingsError.value=e.message;}finally{busy.value=false;}}
async function inspectEngine(phase){const ticket=++engineSequence[phase],provider=draft[phase+'Provider'];engineMessages[phase]='正在检测连接…';engineStates[phase]={};if(!provider){engineMessages[phase]='请选择 AI 引擎';return;}try{const result=await inspectGenerationEngine(provider);if(ticket!==engineSequence[phase])return;engineStates[phase]=result;if(isLocalAiProvider(provider)&&!draft[phase+'BotId'])draft[phase+'BotId']=result.bot||'';engineMessages[phase]=result.ready?'引擎可用':'请先配置连接';}catch(e){if(ticket===engineSequence[phase])engineMessages[phase]=e.message;}}
function configureEngine(phase){document.dispatchEvent(new CustomEvent(isLocalAiProvider(draft[phase+'Provider'])?'xfollower:bind-grok-local':'xfollower:bind-grok-bot',{detail:{provider:draft[phase+'Provider']}}));}
watch(activeTab,tab=>{if(tab==='mutualComments')refresh();},{immediate:true});
const timer=setInterval(()=>{if(activeTab.value==='mutualComments'&&!busy.value)refresh();},5000);
onBeforeUnmount(()=>{clearInterval(timer);sequence++;});
